parse_args() {
  #BINDIR is ./bin unless set be ENV
  # over-ridden by flag below

  BINDIR=${BINDIR:-./bin}
  while getopts "b:dh?x" arg; do
    case "$arg" in
      b) BINDIR="$OPTARG" ;;
      d) log_set_priority 10 ;;
      h | \?) usage "$0" ;;
      x) set -x ;;
    esac
  done
  shift $((OPTIND - 1))
  TAG=$1
}
# this function wraps all the destructive operations
# if a curl|bash cuts off the end of the script due to
# network, either nothing will happen or will syntax error
# out preventing half-done work
cleanup() {
  if [ -n "${tmpdir:-}" ]; then
    rm -rf "${tmpdir}"
    tmpdir=
  fi
}
execute() {
  log_debug "downloading files into ${tmpdir}"
  http_download "${tmpdir}/${TARBALL}" "${TARBALL_URL}"
  verify "${tmpdir}/${TARBALL}"
  srcdir="${tmpdir}/${NAME}"
  (cd "${tmpdir}" && untar "${TARBALL}")
  test ! -d "${BINDIR}" && install -d "${BINDIR}"
  for binexe in $BINARIES; do
    if [ "$OS" = "windows" ]; then
      binexe="${binexe}.exe"
    fi
    install "${srcdir}/${binexe}" "${BINDIR}/"
    log_info "installed ${BINDIR}/${binexe}"
  done
}
get_binaries() {
  case "$PLATFORM" in
    darwin/386) BINARIES="gitrail" ;;
    darwin/amd64) BINARIES="gitrail" ;;
    darwin/arm64) BINARIES="gitrail" ;;
    darwin/armv6) BINARIES="gitrail" ;;
    linux/386) BINARIES="gitrail" ;;
    linux/amd64) BINARIES="gitrail" ;;
    linux/arm64) BINARIES="gitrail" ;;
    linux/armv6) BINARIES="gitrail" ;;
    windows/386) BINARIES="gitrail" ;;
    windows/amd64) BINARIES="gitrail" ;;
    windows/arm64) BINARIES="gitrail" ;;
    windows/armv6) BINARIES="gitrail" ;;
    *)
      log_crit "platform $PLATFORM is not supported.  Make sure this script is up-to-date and file request at https://github.com/${PREFIX}/issues/new"
      exit 1
      ;;
  esac
}
tag_to_version() {
  if [ -z "${TAG}" ]; then
    log_info "checking GitHub for latest tag"
  else
    log_info "checking GitHub for tag '${TAG}'"
  fi
  REALTAG=$(github_release "$OWNER/$REPO" "${TAG}") && true
  if test -z "$REALTAG"; then
    log_crit "unable to find '${TAG}' - use 'latest' or see https://github.com/${PREFIX}/releases for details"
    exit 1
  fi
  # if version starts with 'v', remove it
  TAG="$REALTAG"
  VERSION=${TAG}
}
adjust_format() {
  case ${OS} in
    darwin) FORMAT=zip ;;
    windows) FORMAT=zip ;;
  esac
  # change format (tar.gz or zip) based on OS
  true
}
adjust_os() {
  # adjust archive name based on OS
  true
}
adjust_arch() {
  # adjust archive name based on ARCH
  true
}

gh_supports_safe_attestation() {
  # gh <= 2.92.0 may expose credentials to untrusted TUF mirrors when
  # verifying attestations (GHSA-8xvp-7hj6-mcj9); require the patched release.
  gh --version 2>/dev/null | awk '
    NR == 1 {
      if ($3 !~ /^[0-9]+\.[0-9]+\.[0-9]+$/) {
        exit 1
      }
      split($3, version, ".")
      exit !(version[1] > 2 || (version[1] == 2 && version[2] >= 93))
    }
    END {
      if (NR == 0) {
        exit 1
      }
    }
  '
}
uses_trusted_release_workflow() {
  _gitrail_version=${VERSION#v}
  _gitrail_major=${_gitrail_version%%.*}
  _gitrail_remainder=${_gitrail_version#*.}
  _gitrail_minor=${_gitrail_remainder%%.*}
  _gitrail_patch=${_gitrail_remainder#*.}
  _gitrail_patch=${_gitrail_patch%%[-+]*}

  [ "$_gitrail_major" -gt 0 ] ||
    [ "$_gitrail_minor" -gt 0 ] ||
    [ "$_gitrail_patch" -ge 13 ]
}
verify() {
  artifact=$1
  if is_command gh &&
    gh_supports_safe_attestation &&
    gh attestation verify --help >/dev/null 2>&1; then
    log_info "verifying build provenance for ${artifact##*/}"
    if uses_trusted_release_workflow; then
      gh attestation verify "$artifact" \
        --repo "$OWNER/$REPO" \
        --signer-workflow "$OWNER/$REPO/.github/workflows/release-reusable.yaml"
    else
      gh attestation verify "$artifact" --repo "$OWNER/$REPO"
    fi
    log_info "verified build provenance for ${artifact##*/}"
    return
  fi
  log_info "build provenance verification unavailable; falling back to SHA256"
  http_download "${tmpdir}/${CHECKSUM}" "${CHECKSUM_URL}"
  hash_sha256_verify "$artifact" "${tmpdir}/${CHECKSUM}"
}

